// Prepare tenant data with today's date
const tenants = Array.isArray($input.all()) ? $input.all() : [$input.item.json];
const today = new Date();
const todayStr = today.toISOString().split('T')[0];
const dateStart = todayStr + 'T00:00:00Z';
const dateEnd = todayStr + 'T23:59:59Z';

return tenants.map(tenant => ({
  tenant_id: tenant.id,
  transaction_date: todayStr,
  date_start: dateStart,
  date_end: dateEnd
}));

// Process paid orders into cashbook income entries
const tenantData = $('Prepare Tenant Data').first().json;
const paidOrders = $('Get Today's Paid Orders').first()?.json || [];
const lastBalance = $('Get Opening Balance').first()?.json?.[0]?.balance_after || 0;

let runningBalance = parseFloat(lastBalance);
const incomeEntries = paidOrders.map(order => {
  runningBalance += parseFloat(order.total_amount || 0);
  return {
    tenant_id: tenantData.tenant_id,
    transaction_date: tenantData.transaction_date,
    description: `Sale - Order #${order.id.substring(0, 8)}`,
    reference: order.m_pesa_receipt || order.id,
    amount: parseFloat(order.total_amount || 0),
    type: 'income',
    category: 'sales',
    balance_after: runningBalance
  };
});

return {
  tenant_id: tenantData.tenant_id,
  transaction_date: tenantData.transaction_date,
  opening_balance: lastBalance,
  income_entries: incomeEntries,
  closing_balance: runningBalance,
  total_income: incomeEntries.reduce((sum, e) => sum + e.amount, 0)
};

// Format daily cash position message
const processed = $('Process Income Entries').first().json;
const tenantConfig = $('Get Tenant Config').first()?.json?.[0] || {};

const businessName = tenantConfig.business_name || 'Your Business';
const date = new Date(processed.transaction_date).toLocaleDateString('en-KE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const message = `💰 Daily Cash Position - ${businessName}
──────────────────
📅 ${date}

💵 Opening Balance: KSh ${processed.opening_balance.toLocaleString('en-KE')}
✅ Income Today: KSh ${processed.total_income.toLocaleString('en-KE')}
💰 Closing Balance: KSh ${processed.closing_balance.toLocaleString('en-KE')}

📊 Transactions: ${processed.income_entries.length} sales
──────────────────
Books closed for ${date.split(',')[0]}

Asante! 🎉`;

return {
  tenant_id: processed.tenant_id,
  owner_phone: tenantConfig.owner_phone,
  message: message,
  transaction_date: processed.transaction_date,
  cash_position: {
    opening: processed.opening_balance,
    income: processed.total_income,
    closing: processed.closing_balance
  }
};

// Summary of daily bookkeeping close
const allCloses = $input.all();
const totalIncome = allCloses.reduce((sum, c) => sum + (c.cash_position?.income || 0), 0);
const totalClosing = allCloses.reduce((sum, c) => sum + (c.cash_position?.closing || 0), 0);

return {
  tenants_closed: allCloses.length,
  total_income_recorded: totalIncome,
  total_closing_balance: totalClosing,
  timestamp: new Date().toISOString()
};
